//
//  BudgetAppIntents.swift
//
//  "Hey Siri, log an expense in Budget" — capture without opening the app.
//
//  Copied into the Xcode project by plugins/withAppIntents.js. The ios/
//  directory is gitignored and regenerated by prebuild, so this file is the
//  source of truth; editing the copy under ios/ loses the change.
//
//  WHY THE MAIN APP TARGET, NOT AN EXTENSION
//  Since iOS 16 an AppIntent declared in the app's own target is discovered by
//  the system and run in the app's process, launched in the background. That
//  matters for more than tidiness: an extension would live in a different
//  container, so sharing a file with the app would need an App Group, and an
//  App Group needs the capability provisioned against the App ID in the Apple
//  Developer portal. Staying in the app target means the intent writes to the
//  app's own Documents directory and no provisioning changes at all.
//
//  WHY A FILE AND NOT THE DATABASE
//  The database is expo-sqlite, reached through the JavaScript runtime. When
//  Siri background-launches the app to run an intent, React Native is not up —
//  there is no bridge to call into. So the intent appends a line to a queue and
//  src/lib/pending-capture.ts drains it on the next foreground. The user sees
//  the transaction when they next open the app, which is the right trade: the
//  moment worth catching is standing at the till.
//
//  KNOWN LIMITATION: the phrases and prompts below are English only. The app
//  itself is translated, but Siri phrases are matched by the system from this
//  binary's metadata and would need a String Catalog per language to localise.
//  Worth doing, but it is its own piece of work and does not block capture.
//
import AppIntents
import Foundation

/// Appends one capture to the queue the app drains on next launch.
///
/// Append-only, one JSON object per line. Two shortcuts fired in quick
/// succession each append their own line; rewriting a JSON array would mean
/// read-modify-write, which races itself and loses one of them.
@available(iOS 16.0, *)
enum PendingCaptureQueue {
  static let fileName = "pending-captures.ndjson"

  /// Cap on the file, so a stuck shortcut cannot fill the user's disk. The app
  /// applies its own cap when draining; this one bounds what reaches disk.
  static let maxBytes: UInt64 = 256 * 1024

  static func append(amount: Double, type: String, note: String) throws {
    let docs = try FileManager.default.url(
      for: .documentDirectory, in: .userDomainMask, appropriateFor: nil, create: true
    )
    let url = docs.appendingPathComponent(fileName)

    // The device's local date. Someone logging at 08:00 in Shanghai is a day
    // ahead of UTC, and "today" has to mean theirs — the same rule the JS side
    // follows in dates.ts.
    let formatter = DateFormatter()
    formatter.calendar = Calendar(identifier: .gregorian)
    formatter.locale = Locale(identifier: "en_US_POSIX")
    formatter.dateFormat = "yyyy-MM-dd"

    let payload: [String: Any] = [
      // Client-generated so a replayed drain cannot double-insert.
      "id": UUID().uuidString,
      "amount": abs(amount),
      "type": type,
      "note": note,
      "dateISO": formatter.string(from: Date()),
      "at": Int(Date().timeIntervalSince1970 * 1000),
    ]

    var line = try JSONSerialization.data(withJSONObject: payload, options: [])
    line.append(0x0A)

    guard FileManager.default.fileExists(atPath: url.path) else {
      try line.write(to: url, options: .atomic)
      return
    }

    let attrs = try? FileManager.default.attributesOfItem(atPath: url.path)
    let size = (attrs?[.size] as? NSNumber)?.uint64Value ?? 0
    if size > maxBytes { return }

    let handle = try FileHandle(forWritingTo: url)
    defer { try? handle.close() }
    try handle.seekToEnd()
    try handle.write(contentsOf: line)
  }
}

/// Shared by both intents — the only difference is the sign.
@available(iOS 16.0, *)
private func record(amount: Double, type: String, note: String?) throws {
  try PendingCaptureQueue.append(
    amount: amount,
    type: type,
    note: (note ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
  )
}

@available(iOS 16.0, *)
struct LogExpenseIntent: AppIntent {
  static var title: LocalizedStringResource = "Log an expense"
  static var description = IntentDescription(
    "Record something you spent. It appears in Budget next time you open it."
  )

  /// False on purpose. Opening the app to log twenty for coffee costs the user
  /// the seconds the feature exists to save.
  static var openAppWhenRun: Bool = false

  @Parameter(title: "Amount", requestValueDialog: "How much did you spend?")
  var amount: Double

  @Parameter(title: "What for", requestValueDialog: "What was it for?")
  var note: String?

  static var parameterSummary: some ParameterSummary {
    Summary("Log \(\.$amount) spent on \(\.$note)")
  }

  func perform() async throws -> some IntentResult & ProvidesDialog {
    try record(amount: amount, type: "Expense", note: note)
    return .result(dialog: "Got it. It'll be waiting in Budget.")
  }
}

@available(iOS 16.0, *)
struct LogIncomeIntent: AppIntent {
  static var title: LocalizedStringResource = "Log income"
  static var description = IntentDescription(
    "Record money you received. It appears in Budget next time you open it."
  )

  static var openAppWhenRun: Bool = false

  @Parameter(title: "Amount", requestValueDialog: "How much did you receive?")
  var amount: Double

  @Parameter(title: "What from", requestValueDialog: "What was it from?")
  var note: String?

  static var parameterSummary: some ParameterSummary {
    Summary("Log \(\.$amount) received from \(\.$note)")
  }

  func perform() async throws -> some IntentResult & ProvidesDialog {
    try record(amount: amount, type: "Income", note: note)
    return .result(dialog: "Got it. It'll be waiting in Budget.")
  }
}

/// The phrases Siri listens for, and the entries that show up in Shortcuts.
///
/// `\(.applicationName)` is required in every phrase — the system rejects a
/// phrase without it, because an app may not claim a bare verb.
@available(iOS 16.0, *)
struct BudgetAppShortcuts: AppShortcutsProvider {
  static var appShortcuts: [AppShortcut] {
    AppShortcut(
      intent: LogExpenseIntent(),
      phrases: [
        "Log an expense in \(.applicationName)",
        "Add an expense to \(.applicationName)",
        "Log spending in \(.applicationName)",
        "I spent money in \(.applicationName)",
      ],
      shortTitle: "Log expense",
      systemImageName: "arrow.up.right.circle"
    )
    AppShortcut(
      intent: LogIncomeIntent(),
      phrases: [
        "Log income in \(.applicationName)",
        "Add income to \(.applicationName)",
        "I got paid in \(.applicationName)",
      ],
      shortTitle: "Log income",
      systemImageName: "arrow.down.left.circle"
    )
  }
}
